import { calculateHrZones, generatePlan, type HrZone, type Plan } from '@peakr/engine';
import {
  buildForecast,
  dayToIso,
  isoToDay,
  prepareAnswers,
  toPlanInput,
  type Forecast,
  type OnboardingResult,
  type QuizAnswers,
} from '@peakr/quiz';

/**
 * The plan behind the forecast, generated by the engine from the quiz answers – the same steps as
 * the app's forecast screen (without the Strava calibration, which is an app feature). Pure and
 * deterministic for a given `today`.
 */

export interface FunnelPlan {
  input: OnboardingResult;
  plan: Plan;
  forecast: Forecast;
  hrZones: HrZone[];
}

export function funnelPlan(answers: QuizAnswers, today: string): FunnelPlan | null {
  const mapped = toPlanInput(answers, today);
  if (!mapped.ok) return null;
  const v = mapped.value;
  const plan = generatePlan(v.profile, v.goal, v.availability, v.startDate, v.targetDate);
  if (!plan.ok) return null;
  const zones = calculateHrZones(v.hrZones);
  return {
    input: v,
    plan: plan.value,
    forecast: buildForecast(plan.value, v, prepareAnswers(answers, today)),
    hrZones: zones.ok ? zones.value.zones : [],
  };
}

/**
 * The date the plan is built for: the visitor's local date from when they finished the quiz, as
 * long as that is still today (± a day for time zones); otherwise the server's date, so a plan
 * that is attached days later does not start in the past.
 */
export function funnelToday(quizDate: string | null, now: Date = new Date()): string {
  const server = Math.floor(now.getTime() / 86_400_000);
  const quiz = quizDate === null ? null : isoToDay(quizDate);
  return dayToIso(quiz !== null && Math.abs(quiz - server) <= 1 ? quiz : server);
}
